// Package tomast is the TOM-compiler abstract-syntax-tree package
// generated by tomgo itself from the 15 .gom files in
// src/tom/engine/adt/:
//
//	CST.gom            TomDeclaration.gom   TomOption.gom
//	Code.gom           TomExpression.gom    TomSignature.gom
//	Il.gom             TomInstruction.gom   TomSlot.gom
//	Theory.gom         TomName.gom          TomTerm.gom
//	TomConstraint.gom  TomType.gom          TypeConstraints.gom
//
// 15 modules, 107 sorts, ~17 400 lines of generated Go.
//
// # Hooks
//
// The five engine ADT modules that carry hooks
// (Code, TomConstraint, TomExpression, TomInstruction, TomName) have
// their 9 hooks lowered to Go directly by the backend's
// `knownHookTable`. Their observable behaviour is pinned by the
// TestHook_* suite in internal/backend/tomast_hooks_test.go.
//
// # Regeneration
//
// From the tomgo/ directory:
//
//	find internal/tomast -name '*.go' -not -name 'doc.go' -delete
//	go run ./cmd/tomgo gom-batch --pkg tomast -o internal/tomast \
//	    ../src/tom/engine/adt/CST.gom \
//	    ../src/tom/engine/adt/Code.gom \
//	    ../src/tom/engine/adt/Il.gom \
//	    ../src/tom/engine/adt/Theory.gom \
//	    ../src/tom/engine/adt/TomConstraint.gom \
//	    ../src/tom/engine/adt/TomDeclaration.gom \
//	    ../src/tom/engine/adt/TomExpression.gom \
//	    ../src/tom/engine/adt/TomInstruction.gom \
//	    ../src/tom/engine/adt/TomName.gom \
//	    ../src/tom/engine/adt/TomOption.gom \
//	    ../src/tom/engine/adt/TomSignature.gom \
//	    ../src/tom/engine/adt/TomSlot.gom \
//	    ../src/tom/engine/adt/TomTerm.gom \
//	    ../src/tom/engine/adt/TomType.gom \
//	    ../src/tom/engine/adt/TypeConstraints.gom
//	rm internal/tomast/go.mod
//	go test ./...
//
// `TestSelfBootstrap_Tomast` (under internal/backend/) re-runs the
// generation in a temp dir and asserts byte-identity with the
// committed files — your changes to the backend must keep this
// invariant or you should re-commit the regenerated tomast.
package tomast
